package com.erudit.quiz;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.integration.InternalClients.AiClient;import com.erudit.integration.InternalContracts.*;import com.erudit.quiz.model.QuizModels.Quiz;import com.erudit.quiz.repository.QuizRepository;import com.erudit.quiz.service.QuizService;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.ObjectProvider;
class AiQuizIntegrationTest {@Test void usesValidAiAndFallsBackForFailureOrMalformedResponse(){var repository=mock(QuizRepository.class);var provider=mock(ObjectProvider.class);var ai=mock(AiClient.class);when(provider.getIfAvailable()).thenReturn(ai);when(repository.create(any(),any(),any(),anyInt(),any())).thenAnswer(i->new Quiz(UUID.randomUUID(),i.getArgument(0)));var service=new QuizService(repository,provider,CircuitBreakerRegistry.ofDefaults());doReturn(new AiQuiz("AI question",List.of("A","B"),1)).when(ai).quiz(any());service.create("Quiz","source text",List.of("L1","L2"),0,"Hint");verify(repository).create("Quiz","AI question",List.of("A","B"),1,"Hint");doThrow(new IllegalStateException()).when(ai).quiz(any());service.create("Fallback","source text",List.of("L1","L2"),0,"Hint");verify(repository).create("Fallback","source text",List.of("L1","L2"),0,"Hint");doReturn(new AiQuiz("bad",List.of("one"),4)).when(ai).quiz(any());service.create("Malformed","source text",List.of("L1","L2"),0,"Hint");verify(repository).create("Malformed","source text",List.of("L1","L2"),0,"Hint");}}
